import re

def solve(env, goal):
    def norm(s):
        return s.lower().strip().rstrip('.')

    def parse_goal(g):
        g = norm(g)
        target_obj = None
        target_rec = None
        m = re.search(r'(?:put|place|move)\s+(?:a|an|the)?\s*([a-z0-9_ -]+?)\s+(?:in|on|into|onto)\s+(?:a|an|the)?\s*([a-z0-9_ -]+)$', g)
        if m:
            target_obj = m.group(1).strip()
            target_rec = m.group(2).strip()
        if not target_obj or not target_rec:
            words = g.split()
            if 'in' in words:
                i = words.index('in')
                target_obj = ' '.join(words[max(0, i - 3):i])
                target_rec = ' '.join(words[i + 1:])
            elif 'on' in words:
                i = words.index('on')
                target_obj = ' '.join(words[max(0, i - 3):i])
                target_rec = ' '.join(words[i + 1:])
        def clean(x):
            if not x:
                return None
            x = re.sub(r'^(a|an|the|some)\s+', '', x.strip())
            return x
        return clean(target_obj), clean(target_rec)

    target_obj, target_rec = parse_goal(goal)

    def find_items(text, base):
        for pat in [
            r'\b' + re.escape(base) + r' \d+\b',
            r'\b' + re.escape(base) + r'\b',
        ]:
            found = re.findall(pat, text.lower())
            if found:
                return found
        return []

    def room_recs():
        obs = env.observation.lower()
        recs = []
        for base in [target_rec] + ['shelf', 'countertop', 'cabinet', 'drawer', 'fridge', 'microwave', 'sinkbasin', 'stoveburner', 'table', 'desk', 'bed', 'safe', 'garbagecan', 'toaster', 'coffeemachine']:
            if not base:
                continue
            for m in re.finditer(r'\b' + re.escape(base) + r' \d+\b', obs):
                r = m.group(0)
                if r not in recs:
                    recs.append(r)
        return recs

    def current_recs():
        obs = env.observation.lower()
        recs = []
        for base in [target_rec] + ['shelf', 'countertop', 'cabinet', 'drawer', 'fridge', 'microwave', 'sinkbasin', 'stoveburner', 'table', 'desk', 'bed', 'safe', 'garbagecan', 'toaster', 'coffeemachine']:
            if not base:
                continue
            for m in re.finditer(r'\b' + re.escape(base) + r' \d+\b', obs):
                r = m.group(0)
                if r not in recs:
                    recs.append(r)
        return recs

    def find_obj_in_text(text):
        if not target_obj:
            return None
        for m in re.finditer(r'\b' + re.escape(target_obj) + r' \d+\b', text.lower()):
            return m.group(0)
        return None

    def inv_has_obj(reply):
        if not target_obj:
            return False
        return bool(re.search(r'\b' + re.escape(target_obj) + r' \d+\b', reply.lower()))

    def opened(reply):
        return 'open' in reply.lower() or 'nothing happens' not in reply.lower()

    def step(cmd):
        return env.step(cmd)

    # Determine target receptacle candidates from room description
    candidates = room_recs()
    if not candidates:
        candidates = [target_rec] if target_rec else []

    # First, see if we already know where the object is in observation
    obj = find_obj_in_text(env.observation)
    if obj:
        # Object visible; try to take it
        # But observation might be current location only
        pass

    # Explore receptacles: open and inspect
    visited = set()
    # Ensure we can inspect inventory
    inv_reply = step('inventory')
    if inv_has_obj(inv_reply):
        obj = find_obj_in_text(inv_reply)

    # Search loop
    max_steps = 45
    steps = 0
    while steps < max_steps and not obj:
        # check current observation
        obj = find_obj_in_text(env.observation)
        if obj:
            break
        # try each candidate
        found = False
        for rec in candidates:
            if rec in visited:
                continue
            visited.add(rec)
            steps += 1
            reply = step('go to ' + rec)
            steps += 1
            # open if closed
            if 'closed' in reply.lower() or 'nothing happens' in reply.lower():
                r2 = step('open ' + rec)
                steps += 1
                reply = env.observation
            steps += 1
            reply = step('look')
            steps += 1
            obj = find_obj_in_text(reply)
            if obj:
                found = True
                break
            # if object not found in this receptacle, continue
        if found or obj:
            break
        # refresh candidates from current observation (may reveal new receptacles)
        new_cands = current_recs()
        for r in new_cands:
            if r not in candidates:
                candidates.append(r)
        # also try inventory again
        steps += 1
        reply = step('inventory')
        if inv_has_obj(reply):
            obj = find_obj_in_text(reply)
            break
        if steps >= max_steps:
            break

    if not obj:
        # fallback: try to search admissibly
        adm = env.admissible()
        for c in adm:
            if c.startswith('go to') and target_rec and target_rec in c:
                env.step(c)
                env.step('open ' + c.split('go to ')[1])
                r = env.step('look')
                obj = find_obj_in_text(r)
                if obj:
                    break

    # Take object
    if obj:
        # If object is in current observation, take from nearest receptacle mentioned
        obs = env.observation.lower()
        rec_for_take = None
        for r in current_recs():
            if r in obs:
                rec_for_take = r
                break
        if rec_for_take is None:
            # try to find receptacle in observation containing object
            m = re.search(r'on (?:the )?([a-z]+ \d+).*' + re.escape(obj), obs)
            if m:
                rec_for_take = m.group(1)
        if rec_for_take:
            reply = step('take ' + obj + ' from ' + rec_for_take)
        else:
            reply = step('take ' + obj)
        if 'nothing happens' in reply.lower():
            # try take from current location generically
            for r in current_recs():
                reply = step('take ' + obj + ' from ' + r)
                if 'nothing happens' not in reply.lower():
                    break

    # Move object to target receptacle
    if obj:
        # Choose a target receptacle of the requested type
        target_recs = [r for r in current_recs() if target_rec and target_rec in r]
        if not target_recs:
            target_recs = [r for r in candidates if target_rec and target_rec in r]
        if not target_recs:
            # go to first candidate matching type from room description
            target_recs = [r for r in candidates if target_rec and target_rec in r]
        if target_recs:
            dest = target_recs[0]
            step('go to ' + dest)
            # open if needed
            obs = env.observation.lower()
            if 'closed' in obs:
                step('open ' + dest)
            reply = step('move ' + obj + ' to ' + dest)
            if 'nothing happens' in reply.lower():
                # maybe need open
                step('open ' + dest)
                step('move ' + obj + ' to ' + dest)
        else:
            # fallback: move to any receptacle of correct type if visible
            for r in current_recs():
                if target_rec and target_rec in r:
                    step('move ' + obj + ' to ' + r)
                    break

    return None
